    ) AS n_missing,
    0 AS n_unusable,
    SUM(
        CASE
            WHEN NULLIF(TRIM(rules_failed), '') IS NULL THEN 0
            ELSE 1
        END
    ) AS n_usable
FROM customers_master
UNION ALL
